const items = $input.all();

return items.map((item, index) => {

  const email = item.json?.body?.email || "";
  const text = item.json?.body?.text || "";
  const from = item.json?.from || "unknown";
  const subject = item.json?.subject || "";

  // 🔴 1. Email yoxlaması
  const isValidEmail = typeof email === "string" && email.includes("@");

  // 🔴 2. Text yoxlaması
  const isValidText = typeof text === "string" && text.trim().length > 2;

  // 🔴 3. Error collect (throw yox, flow davam etsin)
  const errors = [];

  if (!isValidEmail) {
    errors.push("Invalid email");
  }

  if (!isValidText) {
    errors.push("Empty or invalid text");
  }

  // 🔴 4. Status flag (sonra IF node-da istifadə edəcəksən)
  const isValid = errors.length === 0;

  return {
    json: {
      email,
      text,
      from,
      subject,

      // əlavə debug məlumatlar
      isValid,
      errors,

      // optional: raw data saxla
      raw: item.json
    }
  };
});
