const priceList = {
  notebook: 5,
  pen: 2,
  laptop: 1000,
  mouse: 20,
  kofe: 3,
  tort: 10
};

// 🔥 LLM-dən gələn JSON string-i parse edirik
let parsed;

try {
  parsed = typeof $json.text === "string"
    ? JSON.parse($json.text)
    : $json;
} catch (e) {
  parsed = { orders: [] };
}

const orders = parsed.orders || [];

let total = 0;

const detailed = orders.map(item => {
  const product = (item.product || "").toLowerCase().trim();
  const quantity = Number(item.quantity) || 0;

  const price = priceList[product] || 0;
  const subtotal = price * quantity;

  total += subtotal;

  return {
    product,
    quantity,
    unit_price: price,
    subtotal
  };
});

return [{
  json: {
    detailed,
    total
  }
}];
